def prod_signs(arr):
    if not arr:
        return None

    magnitude_sum = sum(abs(x) for x in arr)
    sign_product = 1
    for x in arr:
        if x > 0:
            sign_product *= 1
        elif x < 0:
            sign_product *= -1
        else:
            return 0  # If there's a zero, the product of signs is zero

    return magnitude_sum * sign_product

